(()=>{window.sdOpenDirector=async()=>{try{const meta=await(await fetch('/api/meta')).json();const r=await fetch('/api/director/window',{method:'POST',headers:{'Content-Type':'application/json','X-ScoreDeck-Key':meta.controlKey,'X-ScoreDeck-Epoch':meta.serverEpoch,'X-ScoreDeck-Control-Epoch':meta.controlEpoch},body:JSON.stringify({action:'open'})});const d=await r.json();if(!r.ok)throw Error(d.error);}catch{window.open('/director-bar.html','scoredeck-director','width=1360,height=220,resizable=yes');}};
const scan=()=>{const bottom=document.querySelector('.app-shell .sidebar-bottom');if(bottom&&!document.querySelector('#sd-director-open')){const b=document.createElement('button');b.id='sd-director-open';b.className='button';b.textContent='▤　导播控制栏';b.style.cssText='width:100%;font-size:12px';b.setAttribute('aria-describedby','sd-director-help');b.onclick=window.sdOpenDirector;const help=document.createElement('p');help.id='sd-director-help';help.className='sd-director-help';help.append('控制镜头、X 光与游戏 UI。',document.createElement('br'),'请在 Steam → CS2 → 属性 → 启动选项中填写：');const code=document.createElement('code');code.textContent='-netconport 2121 -tools';help.append(code,'修改后重启 CS2。');bottom.prepend(b,help);}};new MutationObserver(scan).observe(document.getElementById('root'),{childList:true,subtree:true});scan();})();
